    fill:"Burette filled to the selected starting volume.",
    pour:"Stopcock opened — titrant is flowing into the flask.",
    endpoint:"Endpoint reached. Read the meniscus at eye level.",
    indicator:"Indicator added. Compare the colour with the scale.",
    sample:"A new sample is on the bench.",
    connect:"Connections made. The circuit is ready.",
    power:"Power switched on. Instruments are live.",
    measure:"Measurement taken from the virtual instruments.",
    reagent:"Reagent added to the sample.",
    heat:"Reaction/heating step performed.",
    slide:"Slide placed on the microscope stage.",
    focus:"Fine focus adjusted. Specimen is sharp.",
    objective:"Objective changed. Field of view updated.",
    object:"Object placed on the optics rail.",
    lens:"Lens moved along the optical bench.",
    screen:"Screen moved until the image is focused.",
    setup:"Apparatus assembled on the bench.",
    action:"Laboratory action completed. Observe the apparatus before measuring."
