const labState={running:false,paused:false,power:false,wires:false,burner:false,liquid:35,temp:20,mass:0,angle:12,timer:0,timerId:null};
function apparatusKind(e){
 const n=(e.name+" "+(e.materials||[]).join(" ")).toLowerCase(),t=e.type;
 if(t==="pendulum"||n.includes("pendulum")||n.includes("free-fall"))return"pendulum";
 if(t==="titration"||n.includes("titration")||n.includes("standard solution")||n.includes("back titration"))return"titration";
 if(["ohm","series","parallel","power"].includes(t)||n.includes("circuit")||n.includes("resistivity")||n.includes("diode")||n.includes("transformer"))return"circuit";
 if(["lens","refraction"].includes(t)||n.includes("lens")||n.includes("refraction")||n.includes("prism")||n.includes("diffraction")||n.includes("interference"))return"optics";
 if(t==="microscope"||n.includes("microscope")||n.includes("staining")||n.includes("slide preparation"))return"microscope";
 if(t==="electrolysis"||n.includes("electrolysis")||n.includes("electrochemical")||n.includes("conductivity"))return"electrolysis";
 if(t==="ph"||n.includes("ph ")||n.includes("acid")||n.includes("alkali")||n.includes("buffer"))return"ph";
 if(t==="food"||n.includes("food test")||n.includes("vitamin")||n.includes("starch")||n.includes("protein"))return"food";
 if(t==="thermal"||n.includes("specific heat")||n.includes("heating")||n.includes("cooling")||n.includes("latent heat")||n.includes("calorimetry"))return"thermal";
 if(t==="gas"||n.includes("gas syringe")||n.includes("boyle"))return"gas";
 if(t==="hooke"||n.includes("spring")||n.includes("elastic"))return"spring";
 if(t==="density"||n.includes("balance")||n.includes("mass")||n.includes("vernier")||n.includes("micrometer")||n.includes("measurement"))return"measurement";
 if(e.subject==="Biology")return"biology";
 if(e.subject==="Environmental")return"environment";
 if(e.subject==="Chemistry")return"chemistry";
 return"general";
}
