 A.optics='<div class="real-lab optics-lab"><div class="optical-rail"><span>0</span><span>20</span><span>40</span><span>60</span><span>80</span><span>100 cm</span></div><div class="raybox-real"><b>RAY BOX</b><i></i></div><div class="object-real"><i></i><b>OBJECT</b></div><div class="lens-real"><i></i><b>LENS</b></div><div class="screen-real"><i></i><b>SCREEN</b></div><div class="light-ray"></div><div class="protractor-real">0°　30°　60°　90°</div><div class="apparatus-caption">OPTICAL BENCH · RAY BOX · LENS · SCREEN · RULER · PROTRACTOR</div></div>';
 A.microscope='<div class="real-lab microscope-lab"><div class="microscope-real"><div class="eyepiece-real"></div><div class="tube-real"></div><div class="nosepiece-real"><i></i><i></i><i></i></div><div class="stage-real"><div class="slide-real"></div></div><div class="focus-real"></div><div class="base-real"></div></div><div class="slide-box-real">SLIDE</div><div class="apparatus-caption">COMPOUND MICROSCOPE · SLIDE · OBJECTIVES · STAGE · FOCUS</div></div>';
 A.electrolysis='<div class="real-lab electrolysis-lab"><div class="electro-supply"><b>DC</b><strong>6 V</strong></div><div class="electro-beaker"><div class="electro-liquid"></div><i class="electrode left"></i><i class="electrode right"></i><span class="bubble"></span><span class="bubble b2"></span></div><div class="lead lead-left"></div><div class="lead lead-right"></div><div class="apparatus-caption">DC SUPPLY · ELECTROLYTE · ELECTRODES · BEAKER · LEADS</div></div>';
 A.ph='<div class="real-lab ph-lab"><div class="tube-rack"><i></i><i></i><i></i><i></i></div><div class="ph-tube"><div id="phFluid"></div></div><div class="dropper-real"></div><div class="ph-meter-real"><b id="phRead">7.0</b><small>pH</small></div><div class="ph-scale">1 2 3 4 5 6 <b>7</b> 8 9 10 11 12 13 14</div><div class="apparatus-caption">TEST TUBES · DROPPER · pH METER · INDICATOR SCALE</div></div>';
 A.food='<div class="real-lab food-lab"><div class="tube-rack"><i></i><i></i><i></i><i></i></div><div class="food-tube"><div id="foodFluid"></div></div><div class="dropper-real"></div><div class="waterbath-real"><b>WATER BATH</b><i></i></div><div class="apparatus-caption">TEST-TUBE RACK · SAMPLE · REAGENT · DROPPER · WATER BATH</div></div>';
 A.thermal='<div class="real-lab thermal-lab"><div class="tripod-real"><i></i><i></i><i></i></div><div class="gauze-real"></div><div class="beaker-real"><div id="heatFluid"></div></div><div class="heater-real"></div><div class="thermometer-real"><i id="thermoLevel"></i><b id="tempRead">20°C</b></div><div class="flame-real" id="flameReal"></div><div class="power-real">HEATER<br><b>50 W</b></div><div class="apparatus-caption">TRIPOD · GAUZE · BEAKER · HEATER · THERMOMETER · POWER SUPPLY</div></div>';
 A.gas='<div class="real-lab gas-lab"><div class="gas-syringe-real"><div id="gasPiston"></div><span>100</span><span>75</span><span>50</span><span>25</span><span>0 cm³</span></div><div class="pressure-real"><b id="pressureRead">101</b><small>kPa</small></div><div class="stand-real"><div class="base-real"></div><div class="upright-real"></div><div class="clamp-real"></div></div><div class="delivery-real"></div><div class="apparatus-caption">GAS SYRINGE · PRESSURE GAUGE · DELIVERY TUBE · CLAMP STAND</div></div>';
 A.spring='<div class="real-lab spring-lab"><div class="stand-real"><div class="base-real"></div><div class="upright-real"></div><div class="clamp-real"></div></div><div class="coil-real" id="coilReal"></div><div class="mass-real"><b id="massRead">100 g</b></div><div class="ruler-real-vertical"><span>0</span><span>5</span><span>10</span><span>15</span><span>20 cm</span></div><div class="apparatus-caption">CLAMP STAND · SPRING · MASS HANGER · RULER</div></div>';
 A.measurement='<div class="real-lab measurement-lab"><div class="balance-real"><div class="balance-pan" id="balancePan"></div><b id="balanceRead">0.0</b><small>g</small></div><div class="cylinder-real"><div id="cylinderFluid"></div><span>100</span><span>80</span><span>60</span><span>40</span><span>20</span><span>0</span></div><div class="caliper-real"><i></i><b>0</b><span>10</span><span>20</span><span>30 mm</span></div><div class="sample-real" draggable="true">SAMPLE</div><div class="apparatus-caption">ELECTRONIC BALANCE · MEASURING CYLINDER · VERNIER CALIPER · SAMPLE</div></div>';
 A.biology='<div class="real-lab biology-lab"><div class="microscope-real"><div class="eyepiece-real"></div><div class="tube-real"></div><div class="nosepiece-real"><i></i><i></i></div><div class="stage-real"><div class="slide-real"></div></div><div class="focus-real"></div><div class="base-real"></div></div><div class="petri-real"><i></i></div><div class="pipette-real"></div><div class="specimen-real">SPECIMEN</div><div class="apparatus-caption">MICROSCOPE · SLIDE · PETRI DISH · PIPETTE · SPECIMEN</div></div>';
