  if(p.scene==="titration") return common+'<div class="specific-lab titration-specific"><div class="burette-real"><div class="burette-liquid" id="specificBurette"></div><div class="stopcock-real"></div></div><div class="drop-stream" id="specificDrop"></div><div class="flask-real"><div class="flask-liquid" id="specificFlask"></div><div class="swirl"></div></div><div class="meniscus-scale">0 10 20 30 40 50 mL</div></div>';
  if(p.scene==="circuit") return common+'<div class="specific-lab circuit-specific"><div class="psu-specific">DC<br><b id="specificVolt">0.0 V</b></div><div class="wire-path"></div><div class="meter-specific" id="specificMeter">0.000 A</div><div class="resistor-specific">R</div><div class="bulb-specific" id="specificBulb">●</div><div class="switch-specific" id="specificSwitch">OPEN</div></div>';
  if(p.scene==="pendulum") return common+'<div class="specific-lab pendulum-specific"><div class="stand-specific"></div><div class="string-specific" id="specificString"></div><div class="bob-specific" id="specificBob"></div><div class="angle-arc"></div><div class="stopwatch-specific" id="specificStopwatch">0.0 s</div></div>';
  if(p.scene==="spring") return common+'<div class="specific-lab spring-specific"><div class="spring-coil" id="specificSpring"></div><div class="spring-mass" id="specificSpringMass">100 g</div><div class="spring-ruler">0&nbsp;&nbsp;10&nbsp;&nbsp;20&nbsp;&nbsp;30 cm</div></div>';
