  if(p.scene==="ph") return common+'<div class="specific-lab ph-specific"><div class="sample-tube"><div class="ph-liquid" id="specificPhLiquid"></div></div><div class="dropper-specific"></div><div class="ph-scale-specific"><span>1</span><span>4</span><span>7</span><span>10</span><span>14</span></div><div class="ph-read-specific" id="specificPhRead">pH —</div></div>';
  if(p.scene==="food") return common+'<div class="specific-lab food-specific"><div class="tube-rack"></div><div class="food-tube"><div id="specificFoodLiquid"></div></div><div class="reagent-dropper"></div><div class="water-bath-specific"></div></div>';
  if(p.scene==="microscope") return common+'<div class="specific-lab microscope-specific"><div class="eyepiece-specific"></div><div class="tube-specific"></div><div class="objective-specific"></div><div class="stage-specific"><div class="slide-specific" id="specificSlide"></div></div><div class="focus-specific"></div><div class="microscope-view" id="microscopeView">SPECIMEN</div></div>';
